import React, { useState, useEffect } from 'react';
import { 
  Grid, Paper, Typography, Box, CircularProgress, Alert,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow
} from '@mui/material';
import { 
  AttachMoney as MoneyIcon,
  ShoppingCart as ExpenseIcon,
  TrendingUp as IncomeIcon
} from '@mui/icons-material';
import { PieChart, Pie, Tooltip, Legend, Cell } from 'recharts';
import { 
  getFinancialSummary, 
  getRecentTransactions,
  getIncome,
  getExpenses
} from '../services/financeService';

const Dashboard = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [summary, setSummary] = useState({
    totalIncome: 0,
    totalExpenses: 0,
    netProfit: 0
  });
  const [recentFinance, setRecentFinance] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const [financialData, income, expenses] = await Promise.all([
          getFinancialSummary(),
          getIncome({ limit: 5 }),
          getExpenses({ limit: 5 })
        ]);
        
        setSummary({
          totalIncome: financialData.totalIncome || 0,
          totalExpenses: financialData.totalExpenses || 0,
          netProfit: financialData.netProfit || 0
        });
        
        setRecentFinance(
          [...income, ...expenses]
            .sort((a, b) => new Date(b.date) - new Date(a.date))
            .slice(0, 5)
        );
        setError(null);
      } catch (err) {
        setError(err.message || 'Failed to load dashboard data');
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const incomeExpenseData = [
    { name: 'Income', value: summary.totalIncome },
    { name: 'Expenses', value: summary.totalExpenses }
  ];

  const COLORS = ['#0088FE', '#FF8042'];

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box my={4}>
        <Alert severity="error">{error}</Alert>
      </Box>
    );
  }

  return (
    <Grid container spacing={3} sx={{ padding: 4, background: '#f0f2f5', minHeight: '100vh' }}>
      <Grid item xs={12}>
        <Paper elevation={5} sx={{ 
          p: 4, 
          borderRadius: 4, 
          background: 'rgba(255, 255, 255, 0.9)', 
          backdropFilter: 'blur(10px)', 
          boxShadow: '0px 8px 20px rgba(0, 0, 0, 0.15)' 
        }}>
          <Typography variant="h5" gutterBottom sx={{ fontWeight: 'bold', color: '#333' }}>
            Financial Summary
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} sm={6} md={4}>
              <Paper elevation={3} sx={{ 
                p: 3, 
                textAlign: 'center',
                borderRadius: 3,
                backgroundColor: '#e8f5e9',
                transition: 'transform 0.3s ease',
                '&:hover': { transform: 'scale(1.05)' }
              }}>
                <IncomeIcon color="success" sx={{ fontSize: 40 }} />
                <Typography variant="h6">Total Income</Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold' }}>
                  ${summary.totalIncome.toFixed(2)}
                </Typography>
              </Paper>
            </Grid>

            <Grid item xs={12} sm={6} md={4}>
              <Paper elevation={3} sx={{ 
                p: 3, 
                textAlign: 'center',
                borderRadius: 3,
                backgroundColor: '#ffebee',
                transition: 'transform 0.3s ease',
                '&:hover': { transform: 'scale(1.05)' }
              }}>
                <ExpenseIcon color="error" sx={{ fontSize: 40 }} />
                <Typography variant="h6">Total Expenses</Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold' }}>
                  ${summary.totalExpenses.toFixed(2)}
                </Typography>
              </Paper>
            </Grid>

            <Grid item xs={12} sm={6} md={4}>
              <Paper elevation={3} sx={{ 
                p: 3, 
                textAlign: 'center',
                borderRadius: 3,
                backgroundColor: summary.netProfit >= 0 ? '#e8f5e9' : '#ffebee',
                transition: 'transform 0.3s ease',
                '&:hover': { transform: 'scale(1.05)' }
              }}>
                <MoneyIcon color={summary.netProfit >= 0 ? "success" : "error"} sx={{ fontSize: 40 }} />
                <Typography variant="h6">Net Profit/Loss</Typography>
                <Typography variant="h4" color={summary.netProfit >= 0 ? 'success.main' : 'error.main'} sx={{ fontWeight: 'bold' }}>
                  ${summary.netProfit.toFixed(2)}
                </Typography>
              </Paper>
            </Grid>
          </Grid>
        </Paper>
      </Grid>

      <Grid item xs={12} md={6}>
        <Paper elevation={5} sx={{ 
          p: 4, 
          height: '100%', 
          borderRadius: 4, 
          background: 'rgba(255, 255, 255, 0.9)', 
          backdropFilter: 'blur(10px)', 
          boxShadow: '0px 8px 20px rgba(0, 0, 0, 0.15)' 
        }}>
          <Typography variant="h5" gutterBottom sx={{ fontWeight: 'bold', color: '#333' }}>
            Income vs Expenses
          </Typography>
          <Box sx={{ display: 'flex', justifyContent: 'center' }}>
            <PieChart width={400} height={300}>
              <Pie
                data={incomeExpenseData}
                cx="50%"
                cy="50%"
                labelLine={false}
                outerRadius={80}
                fill="#8884d8"
                dataKey="value"
                label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
              >
                {incomeExpenseData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </Box>
        </Paper>
      </Grid>

      <Grid item xs={12} md={6}>
        <Paper elevation={5} sx={{ 
          p: 4, 
          height: '100%', 
          borderRadius: 4, 
          background: 'rgba(255, 255, 255, 0.9)', 
          backdropFilter: 'blur(10px)', 
          boxShadow: '0px 8px 20px rgba(0, 0, 0, 0.15)' 
        }}>
          <Typography variant="h5" gutterBottom sx={{ fontWeight: 'bold', color: '#333' }}>
            Recent Financial Transactions
          </Typography>
          {recentFinance.length > 0 ? (
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow sx={{ backgroundColor: '#eeeeee' }}>
                    <TableCell sx={{ fontWeight: 'bold', color: '#555' }}>Type</TableCell>
                    <TableCell sx={{ fontWeight: 'bold', color: '#555' }}>Category</TableCell>
                    <TableCell sx={{ fontWeight: 'bold', color: '#555' }} align="right">Amount</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {recentFinance.map((item) => (
                    <TableRow 
                      key={item._id} 
                      sx={{ 
                        '&:nth-of-type(odd)': { backgroundColor: '#f9f9f9' },
                        '&:hover': { backgroundColor: '#d3e3fc' }
                      }}
                    >
                      <TableCell>{item.amount ? 'Income' : 'Expense'}</TableCell>
                      <TableCell>{item.category?.name || 'N/A'}</TableCell>
                      <TableCell align="right">${item.amount.toFixed(2)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          ) : (
            <Typography>No recent transactions</Typography>
          )}
        </Paper>
      </Grid>
    </Grid>
  );
};

export default Dashboard;
